import { Parser, ReplacementRules, popKeys, hasKey } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, PromptInfo } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList } from './helpers';

const SAMPLER_PARAMS = ['seed', 'steps', 'scale', 'strength', 'seed_mode', 'clip_skip', 'shift'];
const REPLACEMENT_RULES: ReplacementRules = [['scale', 'cfg_scale']];

/**
 * Parser for images generated by Draw Things, which writes a JSON object to the
 * `exif:UserComment` property of an XMP packet
 */
export class DrawThingsParser extends Parser {
  public readonly generator = Generators.DRAWTHINGS;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    const creator = parameters.CreatorTool;
    if (typeof creator !== 'string' || !creator.startsWith('Draw Things')) {
      throw new ParserError('not a Draw Things image');
    }
    const params = readJsonObject(parameters.UserComment);
    if (!hasKey(params, 'c') && !hasKey(params, 'sampler')) {
      throw new ParserError('no Draw Things parameters found');
    }

    const samplerName = take(params, 'sampler') ?? 'unknown';
    const prompt = take(params, 'c');
    const negativePrompt = take(params, 'uc');
    const modelName = take(params, 'model');
    const model = modelName ? createModel({ name: modelName }) : undefined;

    const sampler = createSampler(samplerName, this.normalizeParameters(popKeys(SAMPLER_PARAMS, params), REPLACEMENT_RULES), {
      model,
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    // `v2` repeats every setting in another shape, `profile` holds timings
    delete params.v2;
    return createPromptInfo(this.generator, [sampler], params, parameters);
  }
}
